        $scope.GetSummaryAppointmentPreAuthData = function (req) {


            eHnotePatientDataService.GetAppointmentPreAuthorizationData(req).then(function (resp) {
                console.log(resp);
                if (resp.data.status === 'Success') {
                    if (resp.data.PatientPreAuthorizationId !== 0) {
                        $scope.summaryAppointmentPreAuthDataObj = getSummaryAppointmentPreAuthDataObj();

                        $scope.summaryAppointmentPreAuthDataObj.PatientPreAuthorizationId = resp.data.PatientPreAuthorizationId;
                        $scope.summaryAppointmentPreAuthDataObj.PatientPreAuthDocuments = resp.data.PatientPreAuthDocuments || [];
                        $scope.summaryAppointmentPreAuthDataObj.PayorId = resp.data.PayorId;
                        $scope.summaryAppointmentPreAuthDataObj.OrganizationPayorId = resp.data.OrganizationPayorId;
                        $scope.summaryAppointmentPreAuthDataObj.PayorObj = resp.data.PayorName;
                        $scope.summaryAppointmentPreAuthDataObj.PayorName = resp.data.PayorName;
                        $scope.summaryAppointmentPreAuthDataObj.PayorCode = resp.data.PayorCode;
                        $scope.summaryAppointmentPreAuthDataObj.PlanId = resp.data.PlanId;
                        $scope.summaryAppointmentPreAuthDataObj.OrganizationPlanId = resp.data.OrganizationPlanId;
                        $scope.summaryAppointmentPreAuthDataObj.PlanObj = resp.data.PlanName;
                        $scope.summaryAppointmentPreAuthDataObj.PlanName = resp.data.PlanName;
                        $scope.summaryAppointmentPreAuthDataObj.PlanCode = resp.data.PlanCode;
                        $scope.summaryAppointmentPreAuthDataObj.PreAuthorizationNumber = resp.data.PreAuthNumber1;
                        $scope.summaryAppointmentPreAuthDataObj.VisitReasonId = resp.data.VisitReasonId;
                        $scope.summaryAppointmentPreAuthDataObj.VisitTypeId = resp.data.VisitTypeId;
                        $scope.summaryAppointmentPreAuthDataObj.Remarks = resp.data.Remarks;
                        $scope.summaryAppointmentPreAuthDataObj.ServiceDate = $filter('date')(resp.data.ServiceDate, "MM-dd-yyyy");
                        $scope.summaryAppointmentPreAuthDataObj.ExpiryDate = $filter('date')(resp.data.ExpiryDate, "MM-dd-yyyy");
                        $scope.summaryAppointmentPreAuthDataObj.DeleteInd = resp.data.DeleteInd;
                        $scope.summaryAppointmentPreAuthDataObj.PreAuthNumber1 = resp.data.PreAuthNumber1;
                        $scope.summaryAppointmentPreAuthDataObj.PreAuthNumber2 = resp.data.PreAuthNumber2;
                        $scope.summaryAppointmentPreAuthDataObj.PreAuthNumber3 = resp.data.PreAuthNumber3;
                        $scope.summaryAppointmentPreAuthDataObj.PreAuthNumber4 = resp.data.PreAuthNumber4;
                        $scope.summaryAppointmentPreAuthDataObj.PreAuthNumber5 = resp.data.PreAuthNumber5;
                        $scope.summaryAppointmentPreAuthDataObj.PreAuthorizationCode = resp.data.PreAuthorizationCode;

                        if ($scope.summaryAppointmentPreAuthDataObj.PreAuthNumber2 !== '') {
                            $scope.summaryAppointmentPreAuthDataObj.PreAuthorizationNumber += ", " + $scope.summaryAppointmentPreAuthDataObj.PreAuthNumber2;
                        }
                        if ($scope.summaryAppointmentPreAuthDataObj.PreAuthNumber3 !== '') {
                            $scope.summaryAppointmentPreAuthDataObj.PreAuthorizationNumber += ", " + $scope.summaryAppointmentPreAuthDataObj.PreAuthNumber3;
                        }
                        if ($scope.summaryAppointmentPreAuthDataObj.PreAuthNumber4 !== '') {
                            $scope.summaryAppointmentPreAuthDataObj.PreAuthorizationNumber += ", " + $scope.summaryAppointmentPreAuthDataObj.PreAuthNumber4;
                        }
                        if ($scope.summaryAppointmentPreAuthDataObj.PreAuthNumber5 !== '') {
                            $scope.summaryAppointmentPreAuthDataObj.PreAuthorizationNumber += ", " + $scope.summaryAppointmentPreAuthDataObj.PreAuthNumber5;
                        }


                        if ($scope.summaryAppointmentPreAuthDataObj.PatientPreAuthDocuments.length > 0) {
                            angular.forEach($scope.summaryAppointmentPreAuthDataObj.PatientPreAuthDocuments, function (pitem) {
                                pitem.FileTypeId = pitem.NoteFileTypeId;
                            });
                        }
                    }
                }
            }, function (err) {
                console.log(err);
            });
        };

        function reformAppointmentConsentsandOrgConsents(consentTemplateId) {
            $scope.consentsMainObj.MainConsents = [];

            var filteredOrgConsentTemplateArray = $filter("filter")($scope.consentsMainObj.OrganizationConsents, { "ConsentTemplateId": consentTemplateId }, true);
            if (filteredOrgConsentTemplateArray.length > 0) {

                if ($scope.consentsMainObj.PatientConsents.length === 0) {
                    angular.forEach(filteredOrgConsentTemplateArray[0].ConsentTemplateDetails, function (oitem) {
                        var obj = getnewMainConsentObj();
                        obj.ConsentFormId = oitem.OrganisationConsentFormId;
                        obj.ConsentFormName = oitem.DocumentName;
                        obj.ConsentTemplateId = oitem.ConsentTemplateId;
                        obj.ConsentTypeId = oitem.ConsentTypeId;
                        obj.ConsentTypeName = oitem.ConsentTypeName;
                        obj.PDFcontent = oitem.PDFcontent || "";
                        obj.IsPatientSignRequired = oitem.IsPatientSignRequired;
                        obj.IsDoctorSignRequired = oitem.IsDoctorSignRequired;
                        obj.IsAnesthesistSignRequired = oitem.IsAnesthesistSignRequired;
                        obj.IsCounselorSignRequired = oitem.IsCounselorSignRequired;
                        obj.IsStaffSignRequired = oitem.IsStaffSignRequired;
                        obj.IsGuardianSignRequired = oitem.IsGuardianSignRequired;
                        obj.IsSignRequiredForEachVisit = oitem.IsSignRequiredForEachVisit;
                        obj.IsPatientSignatureDone = false;
                        obj.IsProviderSignatureDone = false;
                        obj.ProviderUserId = 0;
                        obj.ProviderUserName = "";
                        obj.IsStaffSignatureDone = false;
                        obj.StaffUserId = 0;
                        obj.StaffUserName = "";
                        obj.IsCounselorSignatureDone = false;
                        obj.CounselorUserId = 0;
                        obj.CounselorUserName = "";
                        obj.IsAnesthesistSignatureDone = false;
                        obj.AnesthesistUserId = 0;
                        obj.AnesthesistUserName = "";
                        obj.IsGaurdianSignatureDone = false;
                        obj.GaurdianUserId = 0;
                        obj.GaurdianFirstName = "";
                        obj.GaurdianLastName = "";
                        obj.GaurdianRelationShipId = "";
                        $scope.consentsMainObj.MainConsents.push(obj);
                    });
                }
                else {
                    angular.forEach($scope.consentsMainObj.PatientConsents, function (item1) {
                        if (filteredOrgConsentTemplateArray[0].ConsentTemplateDetails.length > 0) {
                            angular.forEach(filteredOrgConsentTemplateArray[0].ConsentTemplateDetails, function (item2) {
                                if (item1.ConsentFormId === item2.OrganisationConsentFormId) {
                                    item2.isConsentAddedForPatient = true;
                                }
                            });
                        }

                    });


                    angular.forEach($scope.consentsMainObj.PatientConsents, function (oitem) {
                        var obj = getnewMainConsentObj();
                        obj.PatientConsentFormId = oitem.PatientConsentDocumentId;
                        obj.ConsentFormId = oitem.ConsentFormId;
                        obj.ConsentFormName = oitem.ConsentFormName;
                        obj.ConsentTemplateId = consentTemplateId;
                        obj.ConsentTypeId = oitem.ConsentTypeId;
                        obj.ConsentTypeName = oitem.ConsentTypeName;
                        obj.HTMLContent = oitem.HTMLContent;
                        obj.S3URL = oitem.S3URL;
                        obj.PDFcontent = oitem.HTMLContent;
                        obj.IsPatientSignRequired = oitem.IsPatientSignRequired;
                        obj.IsDoctorSignRequired = oitem.IsDoctorSignRequired;
                        obj.IsAnesthesistSignRequired = oitem.IsAnesthesistSignRequired;
                        obj.IsCounselorSignRequired = oitem.IsCounselorSignRequired;
                        obj.IsStaffSignRequired = oitem.IsStaffSignRequired;
                        obj.IsGuardianSignRequired = oitem.IsGuardianSignRequired;
                        obj.IsSignRequiredForEachVisit = oitem.IsSignRequiredForEachVisit;
                        obj.IsPatientSignatureDone = oitem.IsPatientSignatureDone;
                        obj.IsProviderSignatureDone = oitem.IsProviderSignatureDone;
                        obj.ProviderUserId = oitem.ProviderUserId || 0;
                        obj.ProviderUserName = oitem.ProviderUserName || "";
                        obj.IsStaffSignatureDone = oitem.IsStaffSignatureDone;
                        obj.StaffUserId = oitem.StaffUserId || 0;
                        obj.StaffUserName = oitem.StaffUserName || "";
                        obj.IsCounselorSignatureDone = oitem.IsCounselorSignatureDone;
                        obj.CounselorUserId = oitem.CounselorUserId || 0;
                        obj.CounselorUserName = oitem.CounselorUserName || "";
                        obj.IsAnesthesistSignatureDone = oitem.IsAnesthesistSignatureDone;
                        obj.AnesthesistUserId = oitem.AnesthesistUserId || 0;
                        obj.AnesthesistUserName = oitem.AnesthesistUserName;
                        obj.IsGaurdianSignatureDone = oitem.IsGaurdianSignatureDone;
                        obj.GaurdianUserId = oitem.GaurdianUserId;
                        obj.GaurdianFirstName = oitem.GaurdianFirstName || "";
                        obj.GaurdianLastName = oitem.GaurdianLastName || "";
                        obj.GaurdianRelationShipId = oitem.GaurdianRelationShipId || 0;
                        obj.IsScannedDocument = oitem.IsScannedDocument;
                        obj.AppointmentId = oitem.AppointmentId;
                        obj.PatientId = oitem.PatientId;
                        obj.DocumentName = oitem.DocumentName;
                        obj.DeleteInd = oitem.DeleteInd || 'Y';
                        obj.PatientSignedDateTime = oitem.PatientSignedDateTime || "";
                        obj.ProviderSignedDateTime = oitem.ProviderSignedDateTime || "";
                        obj.StaffSignedDateTime = oitem.StaffSignedDateTime || "";
                        obj.CounselorSignedDateTime = oitem.CounselorSignedDateTime || "";
                        obj.AnesthesistSignedDateTime = oitem.AnesthesistSignedDateTime || "";
                        obj.GaurdianSignedDateTime = oitem.GaurdianSignedDateTime || "";
                        obj.PatientSignCaptureUserId = oitem.PatientSignCaptureUserId || 0;
                        obj.ProviderSignCaptureUserId = oitem.ProviderSignCaptureUserId || 0;
                        obj.StaffSignCaptureUserId = oitem.StaffSignCaptureUserId || 0;
                        obj.CounselorSignCaptureUserId = oitem.CounselorSignCaptureUserId || 0;
                        obj.AnesthesistSignCaptureUserId = oitem.AnesthesistSignCaptureUserId || 0;
                        obj.GaurdianSignCaptureUserId = oitem.GaurdianSignCaptureUserId || 0;

                        $scope.consentsMainObj.MainConsents.push(obj);
                    });

                    angular.forEach(filteredOrgConsentTemplateArray[0].ConsentTemplateDetails, function (oitem) {
                        if (!oitem.isConsentAddedForPatient) {
                            var obj = getnewMainConsentObj();
                            obj.ConsentFormId = oitem.OrganisationConsentFormId;
                            obj.ConsentFormName = oitem.DocumentName;
                            obj.ConsentTemplateId = oitem.ConsentTemplateId;
                            obj.ConsentTypeId = oitem.ConsentTypeId;
                            obj.ConsentTypeName = oitem.ConsentTypeName;
                            obj.PDFcontent = oitem.PDFcontent;
                            obj.IsPatientSignRequired = oitem.IsPatientSignRequired;
                            obj.IsDoctorSignRequired = oitem.IsDoctorSignRequired;
                            obj.IsAnesthesistSignRequired = oitem.IsAnesthesistSignRequired;
                            obj.IsCounselorSignRequired = oitem.IsCounselorSignRequired;
                            obj.IsStaffSignRequired = oitem.IsStaffSignRequired;
                            obj.IsGuardianSignRequired = oitem.IsGuardianSignRequired;
                            obj.IsSignRequiredForEachVisit = oitem.IsSignRequiredForEachVisit;
                            obj.IsPatientSignatureDone = false;
                            obj.IsProviderSignatureDone = false;
                            obj.ProviderUserId = 0;
                            obj.ProviderUserName = "";
                            obj.IsStaffSignatureDone = false;
                            obj.StaffUserId = 0;
                            obj.StaffUserName = "";
                            obj.IsCounselorSignatureDone = false;
                            obj.CounselorUserId = 0;
                            obj.CounselorUserName = "";
                            obj.IsAnesthesistSignatureDone = false;
                            obj.AnesthesistUserId = 0;
                            obj.AnesthesistUserName = "";
                            obj.IsGaurdianSignatureDone = false;
                            obj.GaurdianUserId = 0;
                            obj.GaurdianFirstName = "";
                            obj.GaurdianLastName = "";
                            obj.GaurdianRelationShipId = "";
                            obj.IsScannedDocument = false;
                            obj.DeleteInd = oitem.DeleteInd || 'N';
                            $scope.consentsMainObj.MainConsents.push(obj);
                        }

                    });
                }


                angular.forEach($scope.consentsMainObj.MainConsents, function (item) {

                    if (!item.IsPatientSignRequired) {
                        item.PatientClass = 'disabled';
                    } else {
                        if (item.IsPatientSignatureDone) {
                            item.PatientClass = 'complete';
                        } else {
                            item.PatientClass = 'incomplete';
                        }
                    }


                    if (!item.IsDoctorSignRequired) {
                        item.ProviderClass = 'disabled';
                    } else {
                        if (item.IsProviderSignatureDone) {
                            item.ProviderClass = 'complete';
                        } else {
                            item.ProviderClass = 'incomplete';
                        }
                    }


                    if (!item.IsStaffSignRequired) {
                        item.StaffClass = 'disabled';
                    } else {
                        if (item.IsStaffSignatureDone) {
                            item.StaffClass = 'complete';
                        } else {
                            item.StaffClass = 'incomplete';
                        }
                    }


                    if (!item.IsGuardianSignRequired) {
                        item.GaurdianClass = 'disabled';
                    } else {
                        if (item.IsGaurdianSignatureDone) {
                            item.GaurdianClass = 'complete';
                        } else {
                            item.GaurdianClass = 'incomplete';
                        }
                    }


                    if (!item.IsAnesthesistSignRequired) {
                        item.AnesthesistClass = 'disabled';
                    } else {
                        if (item.IsAnesthesistSignatureDone) {
                            item.AnesthesistClass = 'complete';
                        } else {
                            item.AnesthesistClass = 'incomplete';
                        }
                    }


                    if (!item.IsCounselorSignRequired) {
                        item.CounselorClass = 'disabled';
                    } else {
                        if (item.IsCounselorSignatureDone) {
                            item.CounselorClass = 'complete';
                        } else {
                            item.CounselorClass = 'incomplete';
                        }
                    }
                });
            }
        }

        $scope.GetPatientAppointmentConsentsById = function () {
            $scope.consentsMainObj.MainConsents = [];
            $scope.consentsMainObj.OrganizationConsents = [];
            $scope.consentsMainObj.PatientConsents = [];

            console.log($scope.SelectedAppointmentObj);

            var serviceTypeId = $scope.SelectedAppointmentObj.VisitTypeId || 0;
            var ApptType = "";
            if ($scope.SelectedAppointmentObj.AppointmentTypeId === 7) {
                serviceTypeId = 0;
                ApptType = "PreOp";
            }

            var obj = {
                "OrganizationId": $scope.HospitalId,
                "PatientId": $scope.SelectedAppointmentObj.PatientId,
                "AppointmentId": $scope.SelectedAppointmentObj.AppointmentID,
                "ServiceTypeId": serviceTypeId,
                "AppointmentType": ApptType
            };

            eHnoteSettingsDataService.GetPatientAppointmentConsentsById(obj).then(function (resp) {


                resp.data.OrganizationConsents = resp.data.OrganizationConsents || [];
                if (resp.data.OrganizationConsents.length > 0) {
                    $scope.consentsMainObj.OrganizationConsents = resp.data.OrganizationConsents;
                    angular.forEach($scope.consentsMainObj.OrganizationConsents, function (oitem) {
                        oitem.isConsentAddedForPatient = false;
                    });
                };

                resp.data.PatientAppointmentConsents = resp.data.PatientAppointmentConsents || [];
                var filteredArray = $filter("filter")($scope.consentsMainObj.OrganizationConsents, { "IsPrimary": "Y" }, true);
                if (resp.data.PatientAppointmentConsents.length > 0) {
                    $scope.consentsMainObj.PatientConsents = resp.data.PatientAppointmentConsents;
                    $scope.consentsMainObj.SelectedConsentTemplateId = $scope.consentsMainObj.PatientConsents[0].ConsentTemplateId || 0;
                    if ($scope.consentsMainObj.SelectedConsentTemplateId === 0) {
                        if (filteredArray.length > 0) {
                            $scope.consentsMainObj.SelectedConsentTemplateId = filteredArray[0].ConsentTemplateId;
                        }
                    }
                    reformAppointmentConsentsandOrgConsents($scope.consentsMainObj.SelectedConsentTemplateId);
                } else {

                    if (filteredArray.length > 0) {
                        $scope.consentsMainObj.SelectedConsentTemplateId = filteredArray[0].ConsentTemplateId;
                        reformAppointmentConsentsandOrgConsents($scope.consentsMainObj.SelectedConsentTemplateId);
                    }
                }


            }, function (err) {
                console.log(err);
            });
        }

        $scope.getApptAdditionalDetails = function (id, type) {
            id = id || null;
            eHnoteMainAppointmentService.getAdditionalApptDetailsById(id).then(function (resp) {

                resp.data = resp.data || [];



                if (resp.data.length > 0) {

                    $scope.parentProfileTab.AppointmentAdditionalDetails = resp.data[0];
                    $scope.AppointmentNotesArray = resp.data[0].AppointmentNotes;
                    $scope.SelectedAppointmentObj.PaymentTypeId = resp.data[0].PaymentTypeId;


                    if (resp.data[0].AppointmentDetails.length > 0) {
                        var obj = resp.data[0].AppointmentDetails[0];

                        var tmpd1 = $filter('date')(obj.AppointmentDate, "yyyy-MM-dd");
                        var tmpd2 = $filter('date')(new Date(), "yyyy-MM-dd");

                        let isPastDate = false;
                        if (tmpd2 > tmpd1) {
                            isPastDate = true;
                        }
                        obj.NoShowReasonId = obj.NoShowReasonId || null;
                        if (isPastDate && obj.IsNoShowAppointment) {
                            $scope.SelectedAppointmentObj.IsNoShowIconInd = true;
                        } else {
                            $scope.SelectedAppointmentObj.IsNoShowIconInd = false;
                        }

                        if (obj.RescheduledAppointmentId !== 0) {
                            $scope.SelectedAppointmentObj.RescheduledAppointmentId = obj.RescheduledAppointmentId;
                            $scope.SelectedAppointmentObj.RescheduledAppointmentDate = obj.RescheduledAppointmentDate;
                            $scope.SelectedAppointmentObj.RescheduledAppointmentStartTime = obj.RescheduledAppointmentStartTime;
                            $scope.SelectedAppointmentObj.RescheduledAppointmentEndTime = obj.RescheduledAppointmentEndTime;
                            $scope.SelectedAppointmentObj.RescheduledDoctorId = obj.RescheduledDoctorId;


                            var starray = $scope.SelectedAppointmentObj.RescheduledAppointmentStartTime.split(":");
                            var st1 = starray[0];
                            var st2 = starray[1];

                            console.log(st1, st2);

                            var stime = getdtTimes(st1, st2);

                            $scope.SelectedAppointmentObj.RescheduledAppointmentStartTime = stime;
                        }

                        $scope.SelectedAppointmentObj.InformantId = obj.InformantId || null;
                        $scope.othernotes.Notes = obj.OtherNotes || "";
                        $scope.othernotes.CreatedDt = obj.ModifiedDt || "";
                        $scope.othernotes.CreatedBy = obj.ModifiedBy || "";

                        var PatientInsuranceplanList = resp.data[0].PatientInsuranceList || [];

                        if (type == 'ShowInsPlanRemarks' && $scope.parentProfileTab.PatientAndApptTab == 2 && $scope.PreviousUrl === '/op') {
                            if (PatientInsuranceplanList.length > 0) {

                                var TempPatientInsuranceList = [];
                                var TempPatientInsuranceList = $filter("filter")(PatientInsuranceplanList, function (item) {
                                    return item.Remarks !== '' && item.IdentifierId == 1;
                                });
                            }
                        }

                        if (PatientInsuranceplanList.length > 0) {
                            let primaryinsurance = $filter('filter')(PatientInsuranceplanList, { 'IsConnectToFutureAppointment': true, 'IdentifierId': 1 }, true) || [];
                            $scope.FutureApptInsuranceObj.IsPrimaryInsuranceAddToFutureAppt = (primaryinsurance.length > 0) ? true : false;
                            let secondaryinsurance = $filter('filter')(PatientInsuranceplanList, { 'IsConnectToFutureAppointment': true, 'IdentifierId': 2 }, true) || [];
                            $scope.FutureApptInsuranceObj.IsSecondaryInsuranceAddToFutureAppt = (secondaryinsurance.length > 0) ? true : false;
                            let otherinsurance = $filter('filter')(PatientInsuranceplanList, { 'IsConnectToFutureAppointment': true, 'IdentifierId': 5 }, true) || [];
                            $scope.FutureApptInsuranceObj.IsOtherInsuranceAddToFutureAppt = (otherinsurance.length > 0) ? true : false;
                        }
                        $scope.SelectedAppointmentObj.PreAdmSurgeryList = [];
                        $scope.SelectedAppointmentObj.SurgeryList = [];

                        $scope.SelectedAppointmentObj.AppointmentTypeId = obj.AppointmentTypeId || null;
                        if (obj.AppointmentTypeId == 7) {
                            $scope.SelectedAppointmentObj.PreAdmSurgeryList = obj.PreAdmSurgeryList || [];
                        } else if (obj.AppointmentTypeId == 4 || obj.AppointmentTypeId == 14) {
                            $scope.SelectedAppointmentObj.SurgeryList = obj.SurgeryList || [];
                        }
                        $scope.SelectedAppointmentObj.OtherProviderDoctorID = resp.data[0].AppointmentDetails[0].OtherProviderDoctorID || 0;
                        $scope.SelectedAppointmentObj.SurgeryReferralDoctorId = resp.data[0].AppointmentDetails[0].SurgeryReferralDoctorId || 0;
                        $scope.SelectedAppointmentObj.ReasonTypeId = resp.data[0].AppointmentDetails[0].ReasonTypeId || 0;
                    }

                } else {
                    $scope.AppointmentNotesArray = [];
                }
            }, function (err) {
                console.log(err);
                alertify.error("Getting data failed");
            });
        };

