        $scope.OrganizationBase64LogoUrlImage = "";

        $scope.toDataURLdata = function (dataURL, callback) {
            var xhr = new XMLHttpRequest();
            xhr.onload = function () {
                var reader = new FileReader();
                reader.onloadend = function () {
                    callback(reader.result);
                };
                reader.readAsDataURL(xhr.response);
            };
            xhr.open('GET', dataURL);
            xhr.responseType = 'blob';
            xhr.send();
        };



        $scope.initOrganizationLogo = function () {

            var printobj = datapersistanceFactory.getItem("printSettingData");
            $scope.toDataURLdata(printobj.PrintHeaderImgUrl, function (dataURL) {
                $scope.OrganizationBase64LogoUrlImage = dataURL || '';
            });
        }

        $scope.ClincalRXDoctorsList = angular.copy($scope.AllHospitalsDataList.AllUsersList);

        $scope.ClincalRXDoctorsList = $filter("filter")($scope.ClincalRXDoctorsList, function (item) {
            return item.RoleId === 1 || item.RoleId === 43;
        });

        $scope.VisitCardprint = function (string) {

            if ($scope.VisitCardApptobj.IsEnableCheckbox == true) {
                var count = 0;
                angular.forEach($scope.UpcomingAppointmentArray, function (item) {
                    if (item.IsVisitcardCheckBox == true) {
                        count++;
                    }
                });
                if (count == 0) {
                    alertify.error("Please Select An Up-coming Appointment");
                    return;
                }
            }

            if ($scope.UpcomingAppointmentArray.length == 0) {
                alertify.error("There is no Upcoming Appointments");
                return;
            }


            var obj = {
                "patientinfo": angular.copy($scope.PatientDetailSummary),
                "organizationLogo": $scope.OrganizationBase64LogoUrlImage || "",
                "UpcomingAppointment": [],
                "AllDoctorsList": $scope.ClincalRXDoctorsList || [],
                "BranchAddress": {
                    "HospitalContact": doctorinfo.doctordata.UserAddress[0].MobileNo,
                    "Address1": doctorinfo.doctordata.UserAddress[0].Address1 || "",
                    "Address2": doctorinfo.doctordata.UserAddress[0].Address2 || "",
                    "Location": doctorinfo.doctordata.UserAddress[0].Location || "",
                    "StateName": doctorinfo.doctordata.UserAddress[0].StateName || "",
                    "PinCode": doctorinfo.doctordata.UserAddress[0].PinCode,
                    "CountryName": doctorinfo.doctordata.UserAddress[0].CountryName,
                    "CityName": doctorinfo.doctordata.UserAddress[0].CityName,
                    "DistrictRegion": doctorinfo.doctordata.UserAddress[0].DistrictRegion,
                    "Latitude": doctorinfo.doctordata.UserAddress[0].Latitude,
                    "Longitude": doctorinfo.doctordata.UserAddress[0].Longitude,
                    "WebsiteUrl": doctorinfo.doctordata.UserAddress[0].NavigationURL || ""
                },
            };
            var today = $filter("date")(new Date(), "yyyy-MM-dd");
            if ($scope.UpcomingAppointmentArray.length > 0) {
                if ($scope.VisitCardApptobj.IsEnableCheckbox == false) {
                    var filter = $filter("filter")($scope.UpcomingAppointmentArray, function (iterator, ind) { return iterator.ConsultationDt !== today; }) || [];
                    if (filter.length > 0) {
                        obj.UpcomingAppointment = angular.copy(filter);
                        angular.forEach(obj.UpcomingAppointment, function (item) {
                            item.shortdate = $filter('date')(new Date(item.ConsultationDt + " " + "00:00:00"), "MM-dd-yyyy");
                            item.shorttime = $filter('date')(new Date(item.ConsultationDt + " " + item.StartTime), "hh:mm a");
                        });
                    }
                } else {
                    var filter = $filter("filter")($scope.UpcomingAppointmentArray, function (iterator, ind) { return iterator.IsVisitcardCheckBox == true; }) || [];
                    if (filter.length > 0) {
                        obj.UpcomingAppointment = angular.copy(filter);
                        angular.forEach(obj.UpcomingAppointment, function (item) {
                            item.shortdate = $filter('date')(new Date(item.ConsultationDt + " " + "00:00:00"), "MM-dd-yyyy");
                            item.shorttime = $filter('date')(new Date(item.ConsultationDt + " " + item.StartTime), "hh:mm a");
                        });
                    }
                }
            }

            USPrintService.generateVisitCardPrint(obj);
            $scope.AddUpdatePrintlog(string);
            angular.forEach($scope.UpcomingAppointmentArray, function (item) {
                item.IsVisitcardCheckBox = false;
            });
            $scope.VisitCardApptobj.IsEnableCheckbox = false;
        }

        $scope.changePatientInsurance = function (obj, parentobj, str) {
            obj = obj || "";
            if (parentobj.PatientInsuranceList.length > 0) {
                let count = 0;
                angular.forEach(parentobj.PatientInsuranceList, function (item) {
                    if (item.PatientInsuranceDetailId == obj.PatientInsuranceDetailId) {
                        count++;
                    }
                });
                if (count > 0) {
                    alertify.error("Selected Insurance is already added!");
                    if (str == "Primary") {
                        $scope.ApptInsuranceObj.PrimaryInsurance = "";
                    } else if (str == "Secondary") {
                        $scope.ApptInsuranceObj.SecondaryInsurance = "";
                    } else {
                        $scope.ApptInsuranceObj.OtherInsurance = "";
                    }
                }
            }
        };


        $scope.AddInsurancetoAppt = function (obj, val) {

            $scope.SelectedAppointmentObj.PatientInsuranceList = $scope.SelectedAppointmentObj.PatientInsuranceList || [];
            if ($scope.SelectedAppointmentObj.PatientInsuranceList.length > 3 || $scope.SelectedAppointmentObj.PatientInsuranceList.length == 3) {
                alertify.error("Max limit reached for insurance");
                return false;
            }
            if (val === 1) {
                if ($scope.ApptInsuranceObj.PrimaryInsurance == "") {
                    alertify.error("Please select primary insurance!");
                    return;
                }
                var filterArray = $filter('filter')($scope.SelectedAppointmentObj.PatientInsuranceList, function (item) { return item.IdentifierId == 1 }) || [];
                if (filterArray.length > 0) {
                    alertify.error("Insurance is already added!");
                    return false;
                }
            }
            if (val === 2) {
                if ($scope.ApptInsuranceObj.SecondaryInsurance == "") {
                    alertify.error("Please select secondary insurance!");
                    return;
                }
                if ($scope.SelectedAppointmentObj.PatientInsuranceList.length == 0) {
                    alertify.error("please Add primary Insurance.");
                    return false;
                }
                var filterArray = $filter('filter')($scope.SelectedAppointmentObj.PatientInsuranceList, function (item) { return item.IdentifierId == 2 }) || [];
                if (filterArray.length > 0) {
                    alertify.error("Insurance is already added!");
                    return false;
                }
            }
            if (val === 5) {
                if ($scope.ApptInsuranceObj.OtherInsurance == "") {
                    alertify.error("Please select insurance!");
                    return;
                }
                if ($scope.SelectedAppointmentObj.PatientInsuranceList.length == 0) {
                    alertify.error("please Add primary Insurance.");
                    return false;
                }
                if ($scope.SelectedAppointmentObj.PatientInsuranceList.length > 0) {
                    var filterArray = $filter('filter')($scope.SelectedAppointmentObj.PatientInsuranceList, function (item) { return item.IdentifierId == 2 });
                    if (filterArray.length == 0) {
                        alertify.error("please Add secondary Insurance.");
                        return false;
                    }
                }
                var filterArray = $filter('filter')($scope.SelectedAppointmentObj.PatientInsuranceList, function (item) { return item.IdentifierId == 5 }) || [];
                if (filterArray.length > 0) {
                    alertify.error("Insurance is already added!");
                    return false;
                }
            }
            let IdentifierId;
            if (val === 1) {
                IdentifierId = 1;
            } else if (val === 2) {
                IdentifierId = 2;
            } else {
                IdentifierId = 5;
            }

            let reqObj = {
                "UserId": $scope.UserId,
                "ParentHospitalId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID || null,
                "AppointmentInsuranceDetailId": 0,
                "AppointmentId": $scope.cacheStorageItem.appointmentid || null,
                "PatientId": $scope.cacheStorageItem.PatientID,
                "InsuranceDetaildId": obj.PatientInsuranceDetailId || null,
                "IdentifierId": IdentifierId,
                // "StatusId": obj.EligibilityStatusId || 0,
                "StatusId": obj.StatusId || 0,
                "EligibilityStatusId": obj.EligibilityStatusId || 0,

                "PaymentTypeId": 2
            };

            eHnoteUserAppointmentDataService.AddInsuranceToAppointment(reqObj).then(function (resp) {
                if (resp.data.status === "Success") {
                    alertify.success("Insurance added Successfully");
                    if (resp.data.AppointmentInsuranceDetailId != 0) {
                        obj.AppointmentInsuranceDetailId = resp.data.AppointmentInsuranceDetailId || 0;
                        obj.PatientAppointmentInsuranceDetailId = resp.data.AppointmentInsuranceDetailId || 0;
                    }
                    if ($scope.parentProfileTab.UpComingApptTab === 2) {
                        $scope.GetOldandNewAllAppointments($scope.cacheStorageItem.PatientID);
                    } else {
                        $scope.GetUpcomingAppointments($scope.cacheStorageItem.PatientID);
                    }
                    if (val === 1) {
                        $scope.ApptInsuranceObj.PrimaryInsurance.IdentifierId = val || 1;
                        $scope.SelectedAppointmentObj.PatientInsuranceList.push($scope.ApptInsuranceObj.PrimaryInsurance);
                        $scope.ApptInsuranceObj.PrimaryInsurance.Remarks = $scope.ApptInsuranceObj.PrimaryInsurance.Remarks || '';
                        if ($scope.ApptInsuranceObj.PrimaryInsurance.Remarks != '' && $scope.parentProfileTab.UpComingApptTab == 2 && $scope.PreviousUrl === '/op') {
                            if ($scope.RoleId == 2 || $scope.RoleId == 71) {
                                $scope.showInsurancePlanAlert($scope.ApptInsuranceObj.PrimaryInsurance);
                            } else if ($scope.UserAccessRights.AllAccessRights.ShowPayorPlanRemarks) {
                                $scope.showInsurancePlanAlert($scope.ApptInsuranceObj.PrimaryInsurance);
                            } else { }

                        }
                        $scope.ApptInsuranceObj.PrimaryInsurance = "";
                    } else if (val == 2) {
                        $scope.ApptInsuranceObj.SecondaryInsurance.IdentifierId = val || 2;
                        $scope.SelectedAppointmentObj.PatientInsuranceList.push($scope.ApptInsuranceObj.SecondaryInsurance);
                        $scope.ApptInsuranceObj.SecondaryInsurance = "";
                    } else if (val == 5) {
                        $scope.ApptInsuranceObj.OtherInsurance = "";
                    }
                }
            });

        };

