                    $scope.file = null;
                    $scope.PatientPCPDocuments = [];
                    $scope.selectApptPCPimagelist = function ($files) {
                        $scope.PatientApptPCPInfo.PatientPCPDocuments = $scope.PatientApptPCPInfo.PatientPCPDocuments || [];
                        $scope.PatientApptPCPInfo.S3URL = '';
                        $scope.file = "";

                        $scope.file = $files;

                        if ($scope.file != null) {
                            if ($scope.file.length > 0) {
                                angular.forEach($scope.file, function (fitem) {
                                    var pName = fitem.name, name = "";
                                    var type = fitem.type.split("/")[1];
                                    if (pName.length > 9) {
                                        name = pName.substring(0, 9) + "..." + "." + type;
                                    } else {
                                        name = angular.copy(pName) + '.' + type;
                                    }

                                    var SelectedDate = $filter("date")(new Date(), "yyyy-MM-dd");
                                    var obj = {
                                        "file": fitem,
                                        "FileTypeId": 10,
                                        "S3URL": "",
                                        "Remarks": "",
                                        "DeleteInd": "N",
                                        "DocumentID": 0,
                                        "SignedDate": SelectedDate,
                                        "DisplayName": fitem.name || "",
                                        "DocumentName": fitem.name || "",
                                        "FileName": fitem.name || "",
                                        "DocumentExt": fitem.type,
                                        "FileExt": fitem.type,
                                    };


                                    if (fitem.type != 'application/pdf') {
                                        $scope.PatientApptPCPInfo.PatientPCPDocuments.push(obj);
                                    }
                                    else {
                                        $scope.PatientApptPCPInfo.PatientPCPDocuments.push(obj);
                                    }
                                });
                            }
                        }
                    };


                    $scope.scanApptReferralImageDocuments = function () {

                        var obj = {
                            "PatientId": $scope.PatientId || null,
                            "AppointmentId": $scope.AppointmentId || null,
                            "PatientName": $scope.PatientName || ""
                        }

                        $scope.mInstanceAdd = $uibModal.open({
                            "templateUrl": "templates/UsNewConsultation/uibpopup/PatientDocumentScanner.html",
                            "backdrop": "static",
                            "size": "md",
                            "resolve": {
                                "mainObject": function () { return obj; }
                            },
                            "windowClass": "modal__eighty-- zindexpopup",
                            "keyboard": false,
                            "controller": "DocumentScannerCtrl",
                        });
                        $scope.mInstanceAdd.result.then(function (result) {
                            if (result !== "") {
                                var SelectedDate = $filter("date")(new Date(), "yyyy-MM-dd");
                                var obj = {
                                    "PatientPCPDocumentId": 0,
                                    "DocumentTypeId": 0,
                                    "DocumentExt": result.FileExt,
                                    "FileExt": result.FileExt,
                                    "DocumentName": result.DocumentName,
                                    "FileName": result.DocumentName,
                                    "S3URL": result.S3URL,
                                    "DeleteInd": "N",
                                    "FileTypeId": 10,
                                    "SignedDate": SelectedDate,
                                    "DisplayName": result.DocumentName || "",
                                    "Remarks": "",
                                }
                                $scope.PatientApptPCPInfo.PatientPCPDocuments.push(obj);
                            }
                        }, function (cancel) {
                        });

                    }

