        $scope.DeletePatientInsurance = function (InsItem) {
            alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'> This insurance will be inactive. Are you want to delete this insurance? </h4>", function () {
                var TempInsuarance = angular.copy(InsItem);
                TempInsuarance.DeleteInd = "Y";
                TempInsuarance.StatusId = 5;
                var param = {
                    "PatientId": $scope.cacheStorageItem.PatientID,
                    "FullName": $scope.Patientobj.FullName,
                    "UserId": $scope.UserId,
                    "HospitalId": $scope.HospitalId,
                    "IsConnectToFutureAppointment": false,
                    "PatientInsuranceDetails": []
                }
                TempInsuarance.ScanDate = TempInsuarance.ScanDate || "";

                if (TempInsuarance.ScanDate != "") {
                    TempInsuarance.ScanDate = $filter("dateFormatter")(TempInsuarance.ScanDate, "-");
                }
                TempInsuarance.VerifiedDate = TempInsuarance.VerifiedDate || '';
                if (TempInsuarance.VerifiedDate != "") {
                    TempInsuarance.VerifiedDate = $filter("dateFormatter")(TempInsuarance.VerifiedDate, "-");
                }

                TempInsuarance.EffectiveDate = TempInsuarance.EffectiveDate || "";
                if (TempInsuarance.EffectiveDate != "") {
                    TempInsuarance.EffectiveDate = moment(TempInsuarance.EffectiveDate).format('YYYY-MM-DD');
                }
                TempInsuarance.ExpiryDate = TempInsuarance.ExpiryDate || "";
                if (TempInsuarance.ExpiryDate != "") {
                    TempInsuarance.ExpiryDate = moment(TempInsuarance.ExpiryDate).format('YYYY-MM-DD');
                }
                param.PatientInsuranceDetails.push(TempInsuarance);

                eHnotePatientDataService.SavePatientInsuranceDetailsById(param, OnAddPatientSuccess, OnAddPatientError);
                function OnAddPatientSuccess(resp) {
                    if (resp.Status === "Success") {
                        console.log("Delete Insurance in patient level");
                        $scope.PatientInsuranceSummary = angular.copy(resp.PatientInsuranceDetails);

                        if ($scope.PatientInsuranceSummary.length > 0) {
                            angular.forEach($scope.PatientInsuranceSummary, function (insitem, index) {
                                insitem.EffectiveDate = insitem.EffectiveDate || "";
                                if (insitem.EffectiveDate != "") {
                                    insitem.EffectiveDate = $filter("date")(insitem.EffectiveDate, "MM-dd-yyyy") || "";
                                }
                                insitem.ExpiryDate = insitem.ExpiryDate || "";
                                if (insitem.ExpiryDate != "") {
                                    insitem.ExpiryDate = $filter("date")(insitem.ExpiryDate, "MM-dd-yyyy") || "";
                                }
                                insitem.ScanDate = insitem.ScanDate || "";
                                if (insitem.ScanDate != "") {
                                    insitem.ScanDate = $filter("date")(insitem.ScanDate, "MM-dd-yyyy") || "";
                                }
                                insitem.VerifiedDate = insitem.VerifiedDate || "";
                                if (insitem.VerifiedDate != "") {
                                    insitem.VerifiedDate = $filter("date")(insitem.VerifiedDate, "MM-dd-yyyy") || "";
                                }
                            });
                        }
                        $scope.GetAppointmentInsuranceDetailsListByStatus();
                    }
                }
                function OnAddPatientError() {
                    alertify.error("Creating  Failed");
                }

            }, function () {
                return;
            });
        };

        $scope.GetAdditionalApptdetail = function () {
            eHnoteMainAppointmentService.getAdditionalApptDetailsById($scope.cacheStorageItem.appointmentid).then(function (resp) {
                $scope.PreAuthObj.PreAuthDetails = resp.data[0].AppointmentPreAuthDetails || [];
                $scope.AppointmentNotesArray = resp.data[0].AppointmentNotes || [];
                if ($scope.AppointmentNotesArray.length > 0) {
                    var count = 0
                    $scope.IsshowNotes = false;
                    angular.forEach($scope.AppointmentNotesArray, function (aitem) {
                        if (aitem.Notes !== '') {
                            aitem.IsNotes = true;
                            count++;
                        }
                        else {
                            aitem.IsNotes = false;
                        }
                    });
                    if (count > 0) {
                        $scope.IsshowNotes = true;
                    }
                }

                if (resp.data[0].AppointmentDetails.length > 0) {
                    $scope.SelectedAppointmentObj = $scope.SelectedAppointmentObj || {};
                    $scope.SelectedAppointmentObj.InformantId = resp.data[0].AppointmentDetails[0].InformantId || 0;

                    $scope.SelectedAppointmentObj.OtherNotes = resp.data[0].AppointmentDetails[0].OtherNotes || "";
                    $scope.SelectedAppointmentObj.OtherNotesCreatedBy = resp.data[0].AppointmentDetails[0].ModifiedBy || "";
                    $scope.SelectedAppointmentObj.OtherNotesCreatedDt = resp.data[0].AppointmentDetails[0].ModifiedDt || "";

                    var tmpd1 = $filter('date')(resp.data[0].AppointmentDetails[0].AppointmentDate, "yyyy-MM-dd");
                    var tmpd2 = $filter('date')(new Date(), "yyyy-MM-dd");

                    let isPastDate = false;
                    if (tmpd2 > tmpd1) {
                        isPastDate = true;
                    }
                    if (isPastDate && resp.data[0].AppointmentDetails[0].IsNoShowAppointment) {
                        $scope.SelectedAppointmentObj.IsNoShowIconInd = true;
                    } else {
                        $scope.SelectedAppointmentObj.IsNoShowIconInd = false;
                    }
                }
                if (resp.data[0].PatientInsuranceList.length > 0) {
                    $scope.SelectedAppointmentObj.PatientInsuranceList = resp.data[0].PatientInsuranceList || [];
                }
                if (resp.data[0].Patient != undefined) {
                    $scope.PatientApptPCPInfo.ExternalComanagerName = resp.data[0].Patient.ExternalComanagerName || "";
                    $scope.PatientApptPCPInfo.InternalComanagerName = resp.data[0].Patient.InternalComanagerName || "";
                    $scope.PatientApptPCPInfo.InternalComanagerId = resp.data[0].Patient.InternalComanagerId || 0;
                    $scope.PatientApptPCPInfo.ExternalComanagerId = resp.data[0].Patient.ExternalComanagerId || 0;
                }
            }, function (err) {
                alertify.error("Getting data failed");
            });
        };



        $scope.initAppointments = function () {
            $scope.SelectedAppointmentObj = "";
            $scope.ShowPatientDetailsList();
            //$scope.GetUpcomingAppointments($scope.cacheStorageItem.PatientID);
            $scope.GetOldandNewAllAppointments($scope.cacheStorageItem.PatientID);
            $scope.getPatientInsuranceDetailsOfPatient();
            $scope.initOrganizationLogo();
            $scope.getBranchSpecializationByIdDetails();
            $scope.GetAdditionalApptdetail();
        }

        /* Appointment history - end */




        $scope.GetAppointmentInsuranceDetailsListByStatus = function () {
            var ApptInsuranceObj = {
                "AppointmentId": $scope.cacheStorageItem.appointmentid,
                "PatientId": $scope.cacheStorageItem.PatientID,
                "SendPlanDetailsInd": 1
            }
            eHnoteInsuranceService.GetAppointmentInsuranceDetailsListByStatus(ApptInsuranceObj).then(function (resp) {
                if (resp.data.status == "Success") {
                    $scope.PatientInsuranceList = resp.data.PatientInsuranceList || [];
                    //alertify.success("Patient  insurance is added to future appointment ");

                }
            }, function (err) {
                alertify.error("Getting Failed");
            });
        }



