        $scope.DownloadTransmissionClaimPdf = function (item) {

            $scope.HospitalAddressArray = [];
            if (doctorinfo.doctordata.UserAddress[0] !== undefined) {
                $scope.HospitalAddressArray = doctorinfo.doctordata.UserAddress[0];

                $scope.PatientStatementInfo.Address1 = $scope.HospitalAddressArray.Address1;
                $scope.PatientStatementInfo.Address2 = $scope.HospitalAddressArray.Address2;
                $scope.PatientStatementInfo.ClinicName = $scope.HospitalAddressArray.ClinicName;
                $scope.PatientStatementInfo.ContactNo = $scope.HospitalAddressArray.ContactNo || "";
                $scope.PatientStatementInfo.PinCode = $scope.HospitalAddressArray.PinCode;
                $scope.PatientStatementInfo.CityName = $scope.HospitalAddressArray.CityName;
                $scope.PatientStatementInfo.StateName = $scope.HospitalAddressArray.StateName;
                $scope.PatientStatementInfo.CountryName = $scope.HospitalAddressArray.CountryName;
                var obj = eHnoteUserDataService.UsMobileFormatChange($scope.PatientStatementInfo.ContactNo);
                $scope.PatientStatementInfo.ContactNo = obj.UsFormatMobileNumber;
            }

            $scope.PatientStatementprintList.push(item);
            $scope.PatientStatementInfo.TotalStatementAmount = item.TotalPatientBalance;

            angular.forEach($scope.PatientStatementprintList, function (item) {
                item.TotalBalance = 0;
                item.TotalPatientAmountData = 0;
                item.OrgBillingProviderListData = {};
                angular.forEach(item.ClaimLineItems, function (citem) {
                    item.TotalBalance += citem.TotalBalance;
                    citem.TotalPatientClaimsAmount = 0;

                    angular.forEach(citem.ClaimLineItemTransactions, function (mitem) {
                        if ([24, 25, 26, 27, 32, 36, 40, 98, 99, 100].includes(mitem.TransactionTypeId)) {
                            citem.TotalPatientClaimsAmount += -(mitem.TransactionAmount) || 0;
                        }
                    });
                    item.TotalPatientAmountData += citem.TotalPatientClaimsAmount || 0;

                    item.OrgBillingProviderListData = $filter("filter")($scope.AllHospitalsDataList.BillingProviderList, { "OrganizationBillingProviderId": citem.BillingProviderId })[0] || {};
                });
            });

            $scope.PatientStatementInfo.IsStatementsListInd = true;

            var element = document.getElementById('transmission-pdf-content');

            var options = {
                margin: 0.1,
                filename: 'TransmissionClaim.pdf',
                image: { type: 'jpeg', quality: 0.98 },
                html2canvas: { scale: 2 },
                jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
            };

            html2pdf().set(options).from(element).save().then(function () {
                $scope.PatientStatementprintList = [];
                $scope.PatientStatementInfo.IsStatementsListInd = false;
            });
        };
